--
-- Name: task_cadence; Type: TYPE; Schema: public; Owner: -
--

CREATE TYPE public.task_cadence AS ENUM (
    'DAILY',
    'WEEKLY',
    'MONTHLY',
    'YEARLY'
);


--
-- Name: task_period(public.task_cadence, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.task_period(p_cadence public.task_cadence, p_tz text, p_at timestamp with time zone DEFAULT now()) RETURNS TABLE(period_index integer, period_key text, period_start timestamp with time zone, period_end timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    CASE p_cadence
      WHEN 'DAILY' THEN b.start_local::date - DATE '1970-01-01'
      WHEN 'WEEKLY' THEN (b.start_local::date - DATE '1970-01-05') / 7
      WHEN 'MONTHLY' THEN EXTRACT(YEAR FROM b.start_local)::int * 12
        + EXTRACT(MONTH FROM b.start_local)::int - 1
      ELSE EXTRACT(YEAR FROM b.start_local)::int
    END,
    CASE p_cadence
      WHEN 'DAILY' THEN to_char(b.start_local, 'YYYY-MM-DD')
      WHEN 'WEEKLY' THEN to_char(b.start_local, 'IYYY-"W"IW')
      WHEN 'MONTHLY' THEN to_char(b.start_local, 'YYYY-MM')
      ELSE to_char(b.start_local, 'YYYY')
    END,
    b.start_local AT TIME ZONE p_tz,
    (b.start_local + b.span) AT TIME ZONE p_tz
  FROM (
    SELECT
      date_trunc(
        CASE p_cadence
          WHEN 'DAILY' THEN 'day'
          WHEN 'WEEKLY' THEN 'week'
          WHEN 'MONTHLY' THEN 'month'
          ELSE 'year'
        END,
        p_at AT TIME ZONE p_tz
      ) AS start_local,
      CASE p_cadence
        WHEN 'DAILY' THEN INTERVAL '1 day'
        WHEN 'WEEKLY' THEN INTERVAL '1 week'
        WHEN 'MONTHLY' THEN INTERVAL '1 month'
        ELSE INTERVAL '1 year'
      END AS span
  ) AS b
$$;


